// P-03: operator installs skill files without manual file copying

#[test]
fn operator_installs_skill_files_without_manual_copying() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let out = run(&dir, &["skill-install", "purpose-walk", "--agent", "claude"]);
    assert!(
        out.status.success(),
        "skill-install failed: {}",
        String::from_utf8_lossy(&out.stderr)
    );
    let installed = dir.path().join(".claude/commands/residual-purpose-walk.md");
    assert!(
        installed.is_file(),
        "expected installed skill at {}",
        installed.display()
    );
    let content = std::fs::read_to_string(&installed).unwrap();
    assert!(
        content.contains("# Purpose Walk"),
        "installed file should contain embedded skill body"
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(
        stdout.contains("Installed"),
        "expected confirmation message, got: {stdout}"
    );
}

#[test]
fn skill_install_places_files_in_each_supported_agent_directory() {
    let dir = TempDir::new().unwrap();
    init(&dir);
    let cases = [
        ("claude", ".claude/commands/residual-naive-draft.md"),
        ("cursor", ".cursor/rules/residual-naive-draft.mdc"),
        ("copilot", ".github/copilot/residual-naive-draft.md"),
        ("agnostic", ".residual/skills/naive-draft.md"),
    ];
    for (agent, rel) in cases {
        let out = run(&dir, &["skill-install", "naive-draft", "--agent", agent]);
        assert!(
            out.status.success(),
            "skill-install --agent {agent} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        let path = dir.path().join(rel);
        assert!(path.is_file(), "missing install path for agent {agent}: {}", path.display());
    }
}

